import { exec, spawn, SpawnOptionsWithoutStdio } from "child_process";
import { debug } from "./cliLog";

export async function execShellExec(cmd: string) {
    await new Promise((resolve, reject) => {
        exec(cmd, (error, stdout, stderr) => {
            if (error) {
                reject(error);
            }
            resolve(stdout ? stdout : stderr);
        });
    });
}
export interface ShellColorOptions {
    colored: boolean
    colorStandard?: string
    colorSection?: string
    colorSubsection?: string
    colorError?: string
}

interface ShellOutputOptions {
    indent: boolean
    prefix: string
}
interface ShellOptions extends ShellOutputOptions {
      /** Current working directory */ cwd?: string, env?: NodeJS.ProcessEnv
}
/**
 * Executes a command via `process.spawn` and captures output while running.
 * The output may be formatted using the options:
 * - `indent`: if true, the output is indented
 * - `prefix`: if set, the prefix is added to every line
 */
export async function execShell(cmd: string, args: string[], colorOptions: ShellColorOptions, options: ShellOptions = {
    indent: true, prefix: '> ', cwd: undefined
}) {

    return new Promise((resolve, reject) => {
        let spawnOptions: SpawnOptionsWithoutStdio | undefined = undefined
        if (options.cwd && options.cwd.length > 0) {
            spawnOptions = { cwd: options.cwd }
        }
        if (options.env) {
            if (!spawnOptions) {
                spawnOptions = { env: options.env }
            } else {
                spawnOptions = { ...spawnOptions, env: options.env }
            }
        }

        // Omit empty lines
        const colorCode = {
            code: undefined
        }
        const consoleLog = (data: any) => {
            const str = formatShellOutput(data, colorOptions, options, colorCode, false);
            if (str != null) console.log(str);
        };
        const consoleErr = (data: any) => {
            const str = formatShellOutput(data, colorOptions, options, colorCode, true);
            if (str != null) console.log(str);
        };

        debug(`Exec: ${options.cwd ? options.cwd : process.cwd()}> ${cmd} ${args.join(' ')}`)
        const spawnedProcess = spawn(cmd, args, spawnOptions);
        spawnedProcess.stdout.on('data', consoleLog);
        spawnedProcess.stderr.on('data', consoleErr);

        spawnedProcess.on('exit', function (code) { // Should probably be 'exit', not 'close'
            // *** Process completed
            resolve(code);
        });
        spawnedProcess.on('error', function (err) {
            // *** Process creation failed
            reject(err);
        });
    });

}

/**
 * Executes a command via `process.spawn` and captures output while running.
 * The output may be formatted using the options:
 * - `indent`: if true, the output is indented
 * - `prefix`: if set, the prefix is added to every line
 */
export async function execShellAndRetrieveOutput(cmd: string, args: string[], options: { cwd: string | undefined }) {

    const output: string[] = [];

    const shellPromise = new Promise((resolve, reject) => {
        let spawnOptions: SpawnOptionsWithoutStdio | undefined = undefined
        if (options.cwd && options.cwd.length > 0) {
            spawnOptions = { cwd: options.cwd }
        }
        const consoleLog = (data: any) => {
            const str = formatShellOutput(data, { colored: false }, { indent: false, prefix: '' }, {}, false);
            if (!str) {
                return;
            }
            const lines = str.split(/\r?\n/);
            debug(lines.map(l => cmd + "> " + l).join('\n'));
            output.push(...lines);
        };
        const consoleErr = (data: any) => {
            const str = formatShellOutput(data, { colored: false }, { indent: false, prefix: cmd }, {}, true);
            if (str != null) console.log(str);
        };

        debug(`Exec: ${options.cwd ? options.cwd : process.cwd()}> ${cmd} ${args.join(' ')}`)

        const spawnedProcess = spawn(cmd, args, spawnOptions);
        spawnedProcess.stdout.on('data', consoleLog);
        spawnedProcess.stderr.on('data', consoleErr);

        spawnedProcess.on('exit', function (code) { // Should probably be 'exit', not 'close'
            // *** Process completed
            resolve(code);
        });
        spawnedProcess.on('error', function (err) {
            // *** Process creation failed
            reject(err);
        });
    });

    await shellPromise;
    return output;
}

export const COLOR_START = "\x1b[";
export const COLOR_END = "m";
export const COLOR_RESET = COLOR_START + "0" + COLOR_END;

function formatShellOutput(data: any, colorOptions: ShellColorOptions, options: ShellOutputOptions,
    colorCode: { code?: string }, isError: boolean): string | null {
    let str = data instanceof Buffer ? data.toString() : String(data);
    str = str.trimEnd();

    const match = str.match(/<<color:\s*([0-9;]+)>>/);
    if (match) {
        colorCode.code = match[1];
        return null;
    }
    if (str.startsWith('<<color:reset>>')) {
        colorCode.code = undefined;
        return null;
    }

    const lines = str.split(/\r?\n/);
    const coloredLines = [];

    let omitEmptyLines = false;
    if (lines.length > 0) {
        if (lines[0].startsWith("  ●")) {
            omitEmptyLines = true;
        }
    }

    for (const line of lines) {
        const trimmedLine = line.trim();
        if (omitEmptyLines && trimmedLine.length == 0) {
            continue;
        }
        if (trimmedLine === "console.log") {
            continue;
        }

        let colorPrefix = '';
        let colorPostFix = '';

        if (colorOptions.colored) {
            let colorCodeSpecial = colorCode.code ? colorCode.code + ";" : '';
            colorPostFix = COLOR_RESET;
            if (line.match(/^\d+\./)) {
                colorPrefix = `${COLOR_START}${colorOptions.colorSubsection}${COLOR_END}`;
                colorCode.code = undefined;
            } else if (line.match(/Processing submission \d+/)) {
                colorPrefix = `${COLOR_START}${colorOptions.colorSection}${COLOR_END}`;
                colorCode.code = undefined;
            } else if (isError && colorOptions.colorError) {
                colorPrefix = `${COLOR_START}${colorCodeSpecial}${colorOptions.colorError}${COLOR_END}`;
            } else if (colorOptions.colorStandard) {
                colorPrefix = `${COLOR_START}${colorCodeSpecial}${colorOptions.colorStandard}${COLOR_END}`;
            } else if (colorCode.code) {
                colorPrefix = `${COLOR_START}${colorCode.code}${COLOR_END}`;
            } else {
                colorPostFix = ''
            }
        }
        let coloredLine = line;

        if (options.prefix) {
            coloredLine = coloredLine.replace(/^/gm, options.prefix);
        }
        if (options.indent) {
            coloredLine = coloredLine.replace(/^/gm, '    ');
        }

        coloredLine = colorPrefix + coloredLine + colorPostFix;
        coloredLines.push(coloredLine);
    }

    return coloredLines.join('\n');
}

export function timestamp() { // Code Pilot: 2019-10-01T12:00:00.000Z
    return new Date().toISOString().replace(/T/, ' ').replace(/\..+/, '');
}
